tape( 'the function computes the L2-norm of a vector `x`', function test( t ) {
	var nrm2;
	var x;

	x = new Float64Array( [ 3.0, -4.0 ] );

	x = array( x );

	nrm2 = dnrm2( x );

	t.strictEqual( nrm2 instanceof ndarray, true, 'returns expected value' );
	t.strictEqual( ndims( nrm2 ), ndims( x )-1, 'returns expected value' );
	t.deepEqual( shape( nrm2 ), [], 'returns expected value' );
	t.strictEqual( nrm2.get(), 5.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports operating on stacks of vectors (default)', function test( t ) {
	var opts;
	var nrm2;
	var x;

	x = new Float64Array( [ 3.0, 4.0, 5.0, 12.0, 8.0, 6.0, 7.0, 24.0 ] );
	opts = {
		'shape': [ 4, 2 ]
	};
	x = array( x, opts );

	nrm2 = dnrm2( x );

	t.strictEqual( nrm2 instanceof ndarray, true, 'returns expected value' );
	t.strictEqual( ndims( nrm2 ), ndims( x )-1, 'returns expected value' );
	t.deepEqual( shape( nrm2 ), [ 4 ], 'returns expected value' );
	t.strictEqual( nrm2.get( 0 ), 5.0, 'returns expected value' );
	t.strictEqual( nrm2.get( 1 ), 13.0, 'returns expected value' );
	t.strictEqual( nrm2.get( 2 ), 10.0, 'returns expected value' );
	t.strictEqual( nrm2.get( 3 ), 25.0, 'returns expected value' );

	t.end();
});

