tape( 'if provided an empty vector, the L2-norm is `0`', function test( t ) {
	var nrm2;
	var x;

	x = array( new Float64Array() );

	nrm2 = dnrm2( x );

	t.strictEqual( nrm2 instanceof ndarray, true, 'returns expected value' );
	t.strictEqual( ndims( nrm2 ), ndims( x )-1, 'returns expected value' );
	t.deepEqual( shape( nrm2 ), [], 'returns expected value' );
	t.strictEqual( nrm2.get(), 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports a strided vector', function test( t ) {
	var nrm2;
	var x;

	x = new Float64Array([
		3.0,  // 0
		99.0,
		-4.0  // 1
	]);
	x = ndarray( 'float64', x, [ 2 ], [ 2 ], 0, 'row-major' );

	nrm2 = dnrm2( x );

	t.strictEqual( nrm2 instanceof ndarray, true, 'returns expected value' );
	t.strictEqual( ndims( nrm2 ), ndims( x )-1, 'returns expected value' );
	t.deepEqual( shape( nrm2 ), [], 'returns expected value' );
	t.strictEqual( nrm2.get(), 5.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports negative strides', function test( t ) {
	var nrm2;
	var x;

	x = new Float64Array([
		5.0,  // 1
		99.0,
		12.0  // 0
	]);
	x = ndarray( 'float64', x, [ 2 ], [ -2 ], 2, 'row-major' );

	nrm2 = dnrm2( x );

	t.strictEqual( nrm2 instanceof ndarray, true, 'returns expected value' );
	t.strictEqual( ndims( nrm2 ), ndims( x )-1, 'returns expected value' );
	t.deepEqual( shape( nrm2 ), [], 'returns expected value' );
	t.strictEqual( nrm2.get(), 13.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports a strided vector having an offset', function test( t ) {
	var nrm2;
	var x;

	x = new Float64Array([
		99.0,
		3.0, // 0
		4.0  // 1
	]);
	x = ndarray( 'float64', x, [ 2 ], [ 1 ], 1, 'row-major' );

	nrm2 = dnrm2( x );

	t.strictEqual( nrm2 instanceof ndarray, true, 'returns expected value' );
	t.strictEqual( ndims( nrm2 ), ndims( x )-1, 'returns expected value' );
	t.deepEqual( shape( nrm2 ), [], 'returns expected value' );
	t.strictEqual( nrm2.get(), 5.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports underlying data buffers with view offsets', function test( t ) {
	var nrm2;
	var x0;
	var x1;

	x0 = new Float64Array([
		1.0,
		3.0,  // 0
		3.0,
		-4.0, // 1
		5.0
	]);

	x1 = new Float64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );

	x1 = ndarray( 'float64', x1, [ 2 ], [ 2 ], 0, 'row-major' );

	nrm2 = dnrm2( x1 );

	t.strictEqual( nrm2 instanceof ndarray, true, 'returns expected value' );
	t.strictEqual( ndims( nrm2 ), ndims( x1 )-1, 'returns expected value' );
	t.deepEqual( shape( nrm2 ), [], 'returns expected value' );
	t.strictEqual( nrm2.get(), 5.0, 'returns expected value' );

	t.end();
});
